questions.solution:
interface Transfer {
  from: string;
  to: string;
  amount: number;
}

function parseTransfer(json: string): Transfer {
  const data: unknown = JSON.parse(json);
  if (typeof data !== "object" || data === null) throw new Error("invalid transfer");
  const { from, to, amount } = data as Record<string, unknown>;
  if (typeof from !== "string" || typeof to !== "string" || typeof amount !== "number" || !(amount > 0)) {
    throw new Error("invalid transfer");
  }
  return { from, to, amount };
}

for (const body of ['{"from":"Ada","to":"Bola","amount":2500}', '{"from":"Ada","to":"Bola","amount":"2500"}']) {
  try {
    const t = parseTransfer(body);
    console.log(`${t.from} -> ${t.to}: ${t.amount}`);
  } catch (error) {
    console.log((error as Error).message);
  }
}

