questions.solution:
function transferFee(amount: number): number {
  if (amount <= 5000) return 10;
  if (amount <= 50000) return 25;
  return 50;
}

function totalFees(json: string): number {
  const data: unknown = JSON.parse(json);
  if (!Array.isArray(data)) return 0;
  let total = 0;
  for (const item of data) {
    if (typeof item === "number" && item > 0) total += transferFee(item);
  }
  return total;
}

console.log(totalFees('[2500, "700", null, 20000, -5]'));
